import sys
from datetime import datetime

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)

def calculate_blocks_and_price(duration_minutes):
    blocks = duration_minutes // 60 + 1
    price = min(blocks * 2.5, 18.0)
    return blocks, price

def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 4:
            print(line.split()[0], "invalid")
            continue
        plate = parts[0]
        entry_date, entry_time = parts[1], parts[2]
        exit_date, exit_time = parts[3], parts[4]
        entry_dt = datetime.strptime(f"{entry_date} {entry_time}", "%Y-%m-%d %H:%M")
        exit_dt = datetime.strptime(f"{exit_date} {exit_time}", "%Y-%m-%d %H:%M")
        if exit_dt <= entry_dt:
            print(plate, "invalid")
            continue
        duration = (exit_dt - entry_dt).total_seconds() / 60
        if duration <= 30:
            fee = 0.0
        else:
            blocks, fee = calculate_blocks_and_price(duration)
        totals[plate] = totals.get(plate, 0) + fee
        print(f"{plate} {(duration // 60):01d}:{(duration % 60):02d} {fee:.2f}")
    print("---")
    for plate in sorted(totals, key=lambda x: (-totals[x], x)):
        print(plate, f"{totals[plate]:.2f}")


if __name__ == "__main__":
    main()
